### 💻 3. `script.js` (A Inteligência)

Este é o ponto crucial. O código JavaScript é projetado para ser *inteligente*: ele checa quais campos de entrada (`V`, `I`, `R`) foram preenchidos e, em seguida, aplica a fórmula correta para calcular a variável faltante.

```javascript
// Função auxiliar para formatar o resultado
function formatNumber(number) {
    if (isNaN(number) || !isFinite(number)) {
        return "Entrada inválida";
    }
    // Arredonda para 3 casas decimais
    return number.toFixed(3); 
}

// Função auxiliar para preencher os valores dos campos rapidamente (Exemplos)
function setInput(v, i) {
    document.getElementById('voltage').value = v;
    document.getElementById('current').value = i;
    // Limpa os outros campos para forçar o cálculo da terceira variável
    document.getElementById('resistance').value = ''; 
    document.getElementById('result').style.display = 'none';
}


/**
 * FUNÇÃO PRINCIPAL: CALCULA OHM'S LAW
 * Verifica quais campos estão preenchidos e resolve a incógnita.
 */
function calculateOhmLaw() {
    // 1. Captura os valores do usuário
    const V = parseFloat(document.getElementById('voltage').value);
    const I = parseFloat(document.getElementById('current').value);
    const R = parseFloat(document.getElementById('resistance').value);

    // 2. Resetar e configurar a interface do resultado
    const resultDiv = document.getElementById('result');
    const resultText = document.getElementById('result-text');
    const resultValue = document.getElementById('result-value');

    resultDiv.style.display = 'none';
    resultValue.textContent = '';
    resultText.textContent = 'Resultado:';

    // 3. Validação de entradas (deve ter pelo menos dois valores válidos)
    const countInputs = [V, I, R].filter(n => !isNaN(n) && isFinite(n) && n !== 0).length;

    if (countInputs < 2) {
        resultDiv.style.display = 'block';
        resultText.textContent = 'Erro!';
        resultValue.textContent = 'Por favor, preencha pelo menos dois valores válidos (V, I ou R).';
        resultDiv.classList.remove('bg-light');
        resultDiv.classList.add('bg-danger');
        return;
    }

    // 4. Lógica de Cálculo
    let calculatedValue;
    let unit = '';
    let foundTarget = false;

    // --- CASO 1: V é o valor desconhecido (V = I * R) ---
    if (isNaN(V)) {
        if (I !== 0 && R !== 0) {
            calculatedValue = I * R;
            unit = 'Volts (V)';
            foundTarget = true;
        }
    } 

    // --- CASO 2: I é o valor desconhecido (I = V / R) ---
    else if (isNaN(I)) {
        if (R !== 0) {
            calculatedValue = V / R;
            unit = 'Amperes (A)';
            foundTarget = true;
        }
    } 

    // --- CASO 3: R é o valor desconhecido (R = V / I) ---
    else if (isNaN(R)) {
        if (I !== 0) {
            calculatedValue = V / I;
            unit = 'Ohms (Ω)';
            foundTarget = true;
        }
    }

    // 5. Exibir o resultado (Se um campo foi deixado em branco)
    if (foundTarget) {
        // Exibir o resultado no campo vazio (melhor UX)
        if (isNaN(V)) document.getElementById('voltage').value = formatNumber(calculatedValue);
        if (isNaN(I)) document.getElementById('current').value = formatNumber(calculatedValue);
        if (isNaN(R)) document.getElementById('resistance').value = formatNumber(calculatedValue);

        // Exibir o resultado no painel de notificação
        resultDiv.style.display = 'block';
        resultText.innerHTML = `<i class="fas fa-check-circle me-2 text-success"></i> Valor Descoberto:`;
        resultValue.textContent = `${formatNumber(calculatedValue)} ${unit}`;
        resultDiv.classList.remove('bg-danger');
        resultDiv.classList.add('bg-light');

    } else {
        // Caso haja erro de divisão por zero ou lógica interna
        resultDiv.style.display = 'block';
        resultText.textContent = 'Erro de Cálculo:';
        resultValue.textContent = 'Verifique se não há divisão por zero ou valores inválidos.';
        resultDiv.classList.remove('bg-light');
        resultDiv.classList.add('bg-danger');
    }
}
```

